import {useCallback, useEffect, useRef, useState} from 'react'
import {Button, Heading, Link, LinkButton, Stack} from '@primer/react'
import {CopilotIcon, DownloadIcon, SyncIcon} from '@primer/octicons-react'

import styles from './Index.module.css'

const REPO_URL = 'https://github.com/github/CopilotForXcode'
const DEEP_LINK = `xcode://agent-plugin-clone?repo=${encodeURIComponent(REPO_URL)}`
const RELEASES_URL = `${REPO_URL}/releases`
const XCODE_APP_STORE_URL = 'https://apps.apple.com/app/xcode/id497799835'

// Custom-scheme launches don't expose a reliable success/failure signal across
// browsers, so after this window we soften the message instead of claiming an
// outcome.
const SOFTEN_MESSAGE_AFTER_MS = 4000

function launchDeepLink() {
  if (typeof window === 'undefined') return
  window.location.href = DEEP_LINK
}

export default function CopilotForXcodeInstallPage() {
  const [status, setStatus] = useState<'launching' | 'waiting'>('launching')
  const cleanupRef = useRef<(() => void) | undefined>(undefined)

  const attemptLaunch = useCallback(() => {
    if (typeof window === 'undefined') return

    // Cancel any timers from a previous launch attempt to avoid races where
    // the older softenTimer fires after a retry and clobbers the new status.
    cleanupRef.current?.()

    // Small delay so the page paints before the OS permission dialog fires.
    const launchTimer = window.setTimeout(launchDeepLink, 500)
    const softenTimer = window.setTimeout(() => setStatus('waiting'), SOFTEN_MESSAGE_AFTER_MS)

    const cleanup = () => {
      window.clearTimeout(launchTimer)
      window.clearTimeout(softenTimer)
    }
    cleanupRef.current = cleanup
    return cleanup
  }, [])

  const handleRetry = useCallback(() => {
    setStatus('launching')
    attemptLaunch()
  }, [attemptLaunch])

  // Auto-launch the deep link on mount. Guarded so SSR is safe.
  useEffect(() => {
    attemptLaunch()
    return () => cleanupRef.current?.()
  }, [attemptLaunch])

  return (
    <div className={styles.page}>
      <header className={styles.header}>
        <div className={styles.headerContent}>
          <CopilotIcon size={32} className={styles.copilotLogo} aria-hidden="true" />
          <span className={styles.headerTitle}>GitHub Copilot</span>
        </div>
      </header>
      <div className={styles.content}>
        <div className={styles.container}>
          <div className={styles.hero}>
            <div className={styles.iconContainer} aria-hidden="true">
              <DownloadIcon size={32} />
            </div>

            <Heading as="h1" className={styles.title}>
              Installing GitHub Copilot for Xcode
            </Heading>
            <p className={styles.description}>
              Xcode should open automatically and begin the installation. Your browser may ask for permission to open
              Xcode. If nothing happens, use the options below.
            </p>
          </div>

          <div className={styles.statusBox}>
            <div className={styles.statusMessage} role="status" aria-live="polite">
              {status === 'launching' ? (
                <>
                  <span className={styles.spinner} aria-hidden="true" />
                  <span>Launching Xcode…</span>
                </>
              ) : (
                <span>Didn&apos;t see Xcode open? Use the options below.</span>
              )}
            </div>
          </div>

          <hr className={styles.divider} />

          <div className={styles.fallbackSection}>
            <Heading as="h2" className={styles.fallbackTitle}>
              Not working? Try these options:
            </Heading>
            <Stack direction="vertical" gap="condensed" padding="none">
              <Button variant="primary" size="large" block leadingVisual={SyncIcon} onClick={handleRetry}>
                Try opening in Xcode again
              </Button>
              <LinkButton
                variant="default"
                size="large"
                block
                leadingVisual={DownloadIcon}
                href={RELEASES_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                Download GitHub Copilot for Xcode directly
              </LinkButton>
            </Stack>
            <div className={styles.repoLink}>
              <Link href={REPO_URL} target="_blank" rel="noopener noreferrer">
                Or go to the GitHub repository
              </Link>
            </div>
          </div>

          <p className={styles.helpText}>
            Don&apos;t have Xcode yet?{' '}
            <Link
              href={XCODE_APP_STORE_URL}
              target="_blank"
              rel="noopener noreferrer"
              inline
              className="Link--inTextBlock"
            >
              Install it from the Mac App Store
            </Link>{' '}
            and try again.
          </p>
        </div>
      </div>
    </div>
  )
}
